        'remparts': 'wall', 'muraille': 'wall',
        'grotte': 'hide', 'thermes': 'thermal', 
        'bibliotheque': 'library', 'bibliothèque': 'library',
        'phare': 'lighthouse', 'tour': 'tower', 
        'statue': 'statue', 'oracle': 'oracle', 'comptoir': 'trade_office', 
