        'senat': 'main', 'sénat': 'main',
        'scierie': 'lumber', 'ferme': 'farm', 
        'carriere': 'stoner', 'carrière': 'stoner',
        'entrepot': 'storage', 'entrepôt': 'storage',
        'mine': 'ironer', "mine d'argent": 'ironer',
        'caserne': 'barracks', 'temple': 'temple', 
